use super::*;

/// What a turn's RECIPIENT receives — the message, who sent it, and how to answer.
///
/// A closed loop says so, because a recipient told only the text would answer into a loop that can no
/// longer take a turn and be refused for reasons it could not have known.
pub fn reply_prompt(
    loop_id: i64,
    recipient: &str,
    speaker: &str,
    text: &str,
    closed: Option<&str>,
) -> String {
    match closed {
        Some(why) => format!(
            "[loop {loop_id}, from {speaker} — now CLOSED ({why})] {text}\n\n\
             The exchange is over; nothing further is expected of you on it."
        ),
        None => format!(
            "[loop {loop_id}, from {speaker}] {text}\n\n\
             Answer with `bsc session reply {loop_id} \"<your answer>\"` — you are `{recipient}` in \
             this loop. Append {ANSWER_SIGNAL} to your final message when it is fully served."
        ),
    }
}
